'use strict';
const $=id=>document.getElementById(id),T=TrashLogic;
let data,all=[],visible=[],selected=null,map,vehicleLayer,stopLayer,lineLayer,userLayer,userPosition=null,preview=null,lastSignature='',markers=new Map(),toastTimer;
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function current(){const c=T.clock();if(preview!==null)c.minute=preview;return c;}
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4500);}
function etaText(n){if(n===0)return '表定停靠中';if(n===null)return '無班次';if(n<60)return `約 ${n} 分鐘`;if(n<1440)return `${Math.floor(n/60)} 小時 ${n%60} 分`;return `${Math.floor(n/1440)} 天後`;}
function when(s,c){if(s.serviceDay===c.day)return '今天';if(s.serviceDay===c.day-1)return '昨晚班次';const d=new Date(s.serviceDay*86400000);return `${d.getUTCMonth()+1}/${d.getUTCDate()}`;}
function matches(r,q){return !q||`${r.name}${r.plate}${r.trip}${r.district}`.includes(q)||r.stops.some(s=>s.address.includes(q));}
function filtered(){const district=$('district').value,q=$('search').value.trim();return all.filter(r=>(!district||r.district===district)&&matches(r,q));}
function initMap(){
 if(!window.L){$('mapError').hidden=false;$('mapError').textContent='地圖未能載入，請重新整理；下方時刻表仍可使用。';return;}
 map=L.map('map',{zoomControl:false}).setView([25.045,121.548],12);L.control.zoom({position:'topright'}).addTo(map);
 const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'}).addTo(map);
 let failures=0;tiles.on('tileerror',()=>{if(++failures>=3)$('mapError').hidden=false;});tiles.on('tileload',()=>{failures=0;$('mapError').hidden=true;});
 vehicleLayer=L.layerGroup().addTo(map);stopLayer=L.layerGroup().addTo(map);lineLayer=L.layerGroup().addTo(map);userLayer=L.layerGroup().addTo(map);
}
function fitResults(){if(!map)return;const points=(selected?[selected]:visible).flatMap(r=>r.stops.map(s=>[s.lat,s.lng]));if(points.length)map.fitBounds(points,{padding:[40,65],maxZoom:15});}
function selectRoute(id,focus=true){const r=all.find(r=>r.id===id);if(!r)throw new Error('找不到這條路線');selected=r;lastSignature='';$('detail').hidden=false;render();drawStops();if(focus&&map)map.fitBounds(r.stops.map(s=>[s.lat,s.lng]),{padding:[60,80],maxZoom:16});}
function drawStops(){if(!map)return;stopLayer.clearLayers();lineLayer.clearLayers();const routes=selected?[selected]:visible;
 if(selected)L.polyline(selected.stops.map(s=>[s.lat,s.lng]),{color:'#188e9a',weight:3,opacity:.7,dashArray:'5 7'}).addTo(lineLayer);
 const drawn=new Set();for(const r of routes){for(const s of r.stops){const k=`${s.lat},${s.lng}`;if(drawn.has(k)&&!selected)continue;drawn.add(k);const marker=L.circleMarker([s.lat,s.lng],{radius:selected?5:3,weight:selected?2:1,color:'#188e9a',fillColor:'white',fillOpacity:.9}).addTo(stopLayer);marker.bindTooltip(()=>{const v=T.stopNext(s,current());return `<strong>${escapeHtml(s.address)}</strong><br>${escapeHtml(T.time(s.arrival))}–${escapeHtml(T.time(s.departure))}<br>下一班：${escapeHtml(etaText(v?.eta??null))}`;});marker.on('click',()=>{selectRoute(r.id,false);marker.openTooltip();});}}
}
function renderVehicles(c){if(!map)return;const valid=new Set();for(const r of visible){const s=T.state(r,c);if(!s.active)continue;valid.add(r.id);let m=markers.get(r.id);if(!m){m=L.marker(s.position,{icon:L.divIcon({className:'',html:'<span class="truck" aria-hidden="true">🚛</span>',iconSize:[32,32],iconAnchor:[16,16]}),title:`${r.district} ${r.name} 推估位置`}).addTo(vehicleLayer);m.on('click',()=>selectRoute(r.id));markers.set(r.id,m);}m.setLatLng(s.position);m.unbindTooltip();m.bindTooltip(`<strong>${escapeHtml(r.district+' '+r.name)}</strong><br>時刻表推估 · ${escapeHtml(etaText(s.eta))}<br>${escapeHtml(s.stop.address)}`);}
 for(const [id,m]of markers){if(!valid.has(id)){vehicleLayer.removeLayer(m);markers.delete(id);}}
}
function renderDetail(c){if(!selected)return;const r=selected,s=T.state(r,c);$('detailDistrict').textContent=`${r.district} · ${r.trip} · ${r.plate}`;$('detailTitle').textContent=r.name;
 $('detailStatus').textContent=s.active?`依時刻表${s.atStop?'目前停靠':'即將抵達'}：${s.stop.address}。${s.atStop?'':etaText(s.eta)+'。'}實際車況與抵達時間可能不同。`:`下一班 ${when(s,c)} ${T.time(s.stop.arrival)} 開始清運。${etaText(s.eta)}。`;
 $('stops').innerHTML=r.stops.map((stop,i)=>{const next=T.stopNext(stop,c);return `<div class="stop ${s.active&&s.stop.id===stop.id?'current':''}"><time>${escapeHtml(T.time(stop.arrival))}</time><button data-stop="${i}" aria-label="在地圖查看 ${escapeHtml(stop.address)}">${escapeHtml(stop.address)}<small>至 ${escapeHtml(T.time(stop.departure))} · ${escapeHtml(etaText(next?.eta??null))}</small></button></div>`;}).join('');
 $('stops').querySelectorAll('button').forEach(b=>b.onclick=()=>{const stop=r.stops[+b.dataset.stop];if(map){map.setView([stop.lat,stop.lng],17);if(window.innerWidth<801)$('detail').hidden=true;}toast(stop.address);});
}
function render(){if(!data)return;const c=current();visible=filtered();
 const scored=visible.map(r=>({r,s:T.state(r,c),distance:userPosition?Math.min(...r.stops.map(s=>T.distance(userPosition,[s.lat,s.lng]))):null}));scored.sort((a,b)=>userPosition?a.distance-b.distance:Number(b.s.active)-Number(a.s.active)||a.s.eta-b.s.eta||a.r.name.localeCompare(b.r.name,'zh-Hant'));
 $('clock').textContent=`${c.date.slice(5).replace('-','/')} ${preview!==null?T.time(preview):c.label}`;
 if(preview===null&&!$('preview').matches(':focus'))$('preview').value=T.time(c.minute);
 $('notice').textContent=`${preview!==null?'預覽今天的時刻表。':T.service(c.day)?'今天例行清運。':'今天為週三／週日，例行停收；跨日班次依前一日計算。'} ${userPosition?'已依你的位置排序。':''}臨時異動、延誤與特殊停收未包含在推估內。`;
 $('count').textContent=scored.filter(x=>x.s.active).length;$('mode').textContent=preview!==null?'預覽時段表定清運中':'表定清運中';$('resultCount').textContent=`${visible.length} 條班次`;
 // Update the list only when minute, filters, or selection changes, keeping keyboard focus stable.
 const signature=[c.day,Math.floor(c.minute),$('district').value,$('search').value,selected?.id,userPosition?.join(',')].join('|');
 if(signature!==lastSignature){lastSignature=signature;$('routes').innerHTML=scored.length?scored.map(({r,s,distance})=>`<button class="route-card ${selected?.id===r.id?'selected':''}" data-route="${r.id}" aria-label="查看 ${escapeHtml(r.district+' '+r.name+' '+r.trip)}"><div class="route-top"><strong>${escapeHtml(r.name)}</strong><span class="status ${s.active?'active':''}">${s.active?'表定清運中':when(s,c)+'下一班'}</span></div><div class="route-meta">${escapeHtml(r.district)} · ${escapeHtml(r.trip)} · ${r.stops.length} 站 ${distance!==null?'· 最近 '+(distance<1?Math.round(distance*1000)+' m':distance.toFixed(1)+' km'):''}</div><div class="route-next"><span>${s.active?'下一站':escapeHtml(T.time(s.stop.arrival))+' 開始'}</span><b>${escapeHtml(etaText(s.eta))}</b></div><span class="address">${escapeHtml(s.stop.address)}</span></button>`).join(''):'<div class="empty">沒有符合的清運路線。試試其他行政區或較短的街道名稱。</div>';$('routes').querySelectorAll('button').forEach(b=>b.onclick=()=>selectRoute(b.dataset.route));}
 renderVehicles(c);renderDetail(c);
}
function changeFilters(){selected=null;$('detail').hidden=true;lastSignature='';render();drawStops();fitResults();}
function webTools(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const ac=new AbortController();window.addEventListener('pagehide',()=>ac.abort(),{once:true});
 const tools=[{name:'filter_collection_routes',title:'篩選台北清運路線',description:'選擇行政區與地址關鍵字，更新地圖與班次列表。位置均依時刻表推估。',inputSchema:{type:'object',properties:{district:{type:'string'},query:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['district','query'].includes(k)))throw Error('輸入無效');const d=input.district??'',q=input.query??'';if(typeof d!=='string'||typeof q!=='string'||q.length>200||![...$('district').options].some(o=>o.value===d))throw Error('行政區或關鍵字無效');$('district').value=d;$('search').value=q;changeFilters();return {estimated:true,count:visible.length,routes:visible.slice(0,20).map(r=>({id:r.id,district:r.district,name:r.name,trip:r.trip}))};}},{name:'view_collection_route',title:'查看清運路線',description:'開啟指定班次的站點、表定時間與推估位置。',inputSchema:{type:'object',properties:{routeId:{type:'string'}},required:['routeId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.routeId!=='string'||Object.keys(input).some(k=>k!=='routeId'))throw Error('路線識別碼無效');selectRoute(input.routeId);return {id:selected.id,name:selected.name,stops:selected.stops.length,estimated:true};}}];for(const t of tools){try{Promise.resolve(ctx.registerTool(t,{signal:ac.signal})).catch(()=>{});}catch{}}
}
async function start(){try{const res=await fetch('data.json');if(!res.ok)throw Error('資料載入失敗');data=await res.json();all=data.routes;initMap();const districts=[...new Set(all.map(r=>r.district))];for(const d of districts){const o=document.createElement('option');o.value=d;o.textContent=d;$('district').append(o);} $('district').onchange=changeFilters;let timer;$('search').oninput=()=>{clearTimeout(timer);timer=setTimeout(changeFilters,200);};$('preview').onchange=()=>{const [h,m]=$('preview').value.split(':').map(Number);if(!Number.isFinite(h)||!Number.isFinite(m))return;preview=h*60+m;lastSignature='';render();};$('live').onclick=()=>{preview=null;lastSignature='';render();};$('fit').onclick=fitResults;$('close').onclick=()=>{selected=null;$('detail').hidden=true;render();drawStops();};$('locate').onclick=()=>{if(!navigator.geolocation){toast('此瀏覽器不支援定位，可直接搜尋街道。');return;}$('locate').disabled=true;$('locate').textContent='定位中…';navigator.geolocation.getCurrentPosition(p=>{$('locate').disabled=false;$('locate').textContent='◎ 找我附近';const pos=[p.coords.latitude,p.coords.longitude];if(T.distance(pos,[25.045,121.548])>45){toast('目前位置離台北市較遠，請選行政區或搜尋地址。');return;}userPosition=pos;$('district').value='';$('search').value='';changeFilters();if(map){userLayer.clearLayers();L.circleMarker(pos,{radius:7,color:'white',weight:3,fillColor:'#3378da',fillOpacity:1}).addTo(userLayer).bindTooltip('你的位置');map.setView(pos,15);}toast('已按最近清運點排序；距離為直線距離。');},()=>{$('locate').disabled=false;$('locate').textContent='◎ 找我附近';toast('無法取得位置，請開啟定位權限或搜尋街道。');},{timeout:10000,maximumAge:60000});};render();drawStops();webTools();setInterval(render,10000);}catch(error){$('notice').textContent='清運資料載入失敗，請重新整理再試。';$('routes').innerHTML='<div class="empty">無法載入清運資料。你仍可透過下方官方連結查詢。</div>';console.error(error);}}
start();
